function rotationDroite(tab, k) {
  const n = tab.length;
  if (n === 0) return [];
  // On réduit k modulo la taille du tableau
  k = k % n;
  if (k === 0) return [...tab];

  // La dernière partie de longueur k va au début
  const debut = tab.slice(n - k);
  const fin = tab.slice(0, n - k);
  return [...debut, ...fin];
}
